import numpy as np


def clean(rows):
    speeds = []
    seen = set()
    for row in rows:
        try:
            hour, speed_text = row.split(',', 1)
        except ValueError:
            continue
        hour = hour.strip()
        speed_text = speed_text.strip()
        try:
            speed = float(speed_text)
        except ValueError:
            continue
        if hour in seen:
            continue
        seen.add(hour)
        speeds.append(speed)
    return speeds


